import {getSession,signIn,signOut,getCatalog,getInstructorProfile,createLiveSession,getLiveSessions,getParticipants,updateParticipant,getTrainingGroups,createTrainingGroup,updateTrainingGroup,getTrainingGroupResults,updateTrainingGroupGrading,getFinalExams,getFinalExam,createFinalExam,updateFinalExam,createFinalExamQuestion,deleteFinalExamQuestion,finalExamQrUrl,getPracticalExperiences,createPracticalExperience,updatePracticalExperience,issueCertificate,revokeCertificate,certificatePdfUrl,groupCertificatesPdfUrl,regenerateParticipantCode,participantsExportUrl,updateLiveSession,createQuestion,createTheme,createChapterAndQuiz,updateQuestion,deleteQuestionById,updateAnswerOption,deleteThemeById,deleteChapterById,getArchives,archiveItem,restoreArchive,deleteArchive,rpc} from './api.js';
const app=document.querySelector('#app');let catalog=[],live=[],participants=[],groups=[],archives=[],pilotPoller=null;
const performanceState={themeId:'',chapterId:'',sessionId:'',questionPage:0};
const participantState={search:'',themeId:'',chapterId:'',sessionId:''};
const performancePageSize=5;
const listPageSize=10;
const listPages={participants:0,groups:0,exams:0,attempts:0,experiences:0,certificates:0,performance:0,archives:0};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flat=()=>catalog.flatMap(t=>(t.chapters||[]).map(c=>({theme:t,chapter:c,quiz:Array.isArray(c.quizzes)?c.quizzes[0]:c.quizzes})));
const learnerOrigin=location.origin;
const urlFor=code=>`${learnerOrigin}/learner.html?session=${encodeURIComponent(code)}`;
const code=()=>Array.from(crypto.getRandomValues(new Uint8Array(8)),value=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[value%32]).join('');
const qr=c=>`/api/qr?code=${encodeURIComponent(c)}`;
function shell(body){app.innerHTML=`<header class="topbar"><a class="brand" href="./instructor.html"><span class="logo">TS</span><span>Formation <small>· Instructeur</small></span></a><a class="link-button" href="./learner.html">🎓 Apprenant</a></header><main class="container animate-in">${body}</main>`}
function togglePassword(inputId,button){const input=document.querySelector(`#${inputId}`);if(!input)return;const visible=input.type==='text';input.type=visible?'password':'text';button.textContent=visible?'👁️':'🙈';button.setAttribute('aria-label',visible?'Afficher le mot de passe':'Masquer le mot de passe');button.title=visible?'Afficher le mot de passe':'Masquer le mot de passe'}
function login(){shell(`<div class="login"><p class="eyebrow">Accès instructeur / auditeur</p><h1>Connexion</h1><div class="card"><label>Email</label><input id="email" type="email" autocomplete="email"><label>Mot de passe</label><div class="password-field"><input id="password" type="password" autocomplete="current-password"><button class="password-toggle" type="button" aria-label="Afficher le mot de passe" title="Afficher le mot de passe" onclick="togglePassword('password',this)">👁️</button></div><p><button class="button" onclick="doLogin()">Se connecter →</button></p><p id="error" class="notice hidden"></p></div></div>`)}
async function doLogin(){try{await signIn(document.querySelector('#email').value,document.querySelector('#password').value);await load();render()}catch(e){const x=document.querySelector('#error');x.textContent=e.message;x.classList.remove('hidden')}}
async function load(){[catalog,live,participants,groups,archives]=await Promise.all([getCatalog(),getLiveSessions(),getParticipants(),getTrainingGroups(),getArchives()])}
function pageItems(items,key){const pages=Math.max(1,Math.ceil(items.length/listPageSize));listPages[key]=Math.min(Math.max(0,listPages[key]||0),pages-1);const start=listPages[key]*listPageSize;return{items:items.slice(start,start+listPageSize),start,end:Math.min(start+listPageSize,items.length),pages}}
function paginationHtml(key,total){if(!total)return'';const start=(listPages[key]||0)*listPageSize,end=Math.min(start+listPageSize,total),pages=Math.max(1,Math.ceil(total/listPageSize));return`<nav class="list-pagination" aria-label="Pagination"><span>${start+1}–${end} sur ${total}</span><button class="icon-button" type="button" onclick="changeListPage('${key}',-1)" ${listPages[key]===0?'disabled':''} aria-label="Page précédente">‹</button><button class="icon-button" type="button" onclick="changeListPage('${key}',1)" ${listPages[key]>=pages-1?'disabled':''} aria-label="Page suivante">›</button></nav>`}
function changeListPage(key,direction){listPages[key]=Math.max(0,(listPages[key]||0)+direction);if(key==='participants')return renderParticipants();if(key==='groups')return renderTrainingGroups();if(key==='exams')return renderFinalExamPanel();if(key==='archives')return renderArchives();if(key==='performance')return showPerformance(false);if(key==='certificates')return selectCertificateGroupWeighted(document.querySelector('#certificateGroup')?.value);if(key==='experiences')return selectExperienceGroup(activeExperienceGroupId);if(key==='attempts'&&activeFinalExamId)return selectFinalExam(activeFinalExamId,false)}
function render(){if(!getSession())return login();const items=flat();shell(`<div class="layout"><aside class="sidebar"><p>Navigation</p><button class="nav-button active" onclick="panel('create',this)">📡 Sessions live</button><button class="nav-button" onclick="panel('questions',this)">🧩 Questions</button><button class="nav-button" onclick="panel('pilot',this)">🎮 Piloter le quiz</button><button class="nav-button" onclick="panel('archives',this)">🗃️ Archives</button><button class="nav-button" onclick="panel('participants',this)">👥 Participants</button><button class="nav-button" onclick="panel('performance',this)">🏆 Performances</button><button class="nav-button" onclick="logout()">↪ Déconnexion</button></aside><section><div id="create" class="panel active"><p class="eyebrow">Créer et diffuser</p><h1>Nouvelle session live ✦</h1><div class="card"><label>Thème · chapitre</label><select id="quizSelect">${items.map(i=>`<option value="${i.quiz?.id}">${esc(i.theme.name)} · ${esc(i.chapter.title)}</option>`).join('')}</select><label>Nom de la session</label><input id="sessionTitle" placeholder="Ex. Formation équipe matin"><p><button class="button" onclick="createSession()">Générer le QR code ✨</button></p></div><div id="createdSession"></div></div><div id="questions" class="panel"><div class="row"><div><p class="eyebrow">Bibliothèque</p><h1>Questions par thème</h1></div><button class="button" onclick="showQuestionForm()">＋ Ajouter une question</button></div><div id="questionForm"></div><div class="tabs theme-tags">${catalog.map((t,i)=>`<button class="tab ${i?'':'active'}" onclick="showTheme('${t.id}',this)">🏷️ ${esc(t.name)}</button>`).join('')}</div><div id="accordions" class="accordion-list"></div></div><div id="pilot" class="panel"><p class="eyebrow">Contrôle direct</p><div class="row"><h1>Piloter le quiz</h1><button class="button secondary" onclick="refresh()">↻ Actualiser</button></div><div id="pilotRows"></div></div><div id="archives" class="panel"><div class="row"><div><p class="eyebrow">Gestion manuelle</p><h1>Archives</h1></div><button class="button secondary" onclick="exportArchives()">Exporter la liste CSV</button></div><p class="muted">Restaurez un élément ou, si vous êtes superadministrateur, supprimez-le définitivement.</p><div id="archiveRows"></div></div><div id="participants" class="panel"><div class="row"><div><p class="eyebrow">Registre de la formation</p><h1>Participants</h1></div><a class="button" href="${participantsExportUrl()}">Exporter le fichier CSV</a></div><div id="participantRows"></div></div><div id="performance" class="panel"><p class="eyebrow">Analyse des résultats</p><h1>Performances individuelles</h1><div class="card performance-filters"><div class="performance-filter-step"><p><b>1. Sélectionnez un thème</b></p><div id="performanceThemes" class="tabs performance-tags">${catalog.map(theme=>`<button class="tab" type="button" data-theme-id="${theme.id}" onclick="selectPerformanceTheme('${theme.id}')">🏷️ ${esc(theme.name)}</button>`).join('')||'<span class="muted">Aucun thème disponible.</span>'}</div></div><div class="performance-filter-step"><p><b>2. Sélectionnez un chapitre</b></p><div id="performanceChapters" class="tabs performance-tags"><span class="muted">Choisissez d’abord un thème.</span></div></div><div id="performanceSession"></div></div><div id="performanceRows" class="card performance-results">Sélectionnez un thème, puis un chapitre pour afficher les performances.</div></div></section></div>`);showTheme(catalog[0]?.id);renderPilot();renderParticipants();renderArchives()}
function panel(id,b){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav-button').forEach(x=>x.classList.remove('active'));b?.classList.add('active');if(id==='pilot')startPilotAutoRefresh();else stopPilotAutoRefresh();if(id==='participants')refreshParticipants()}
function startPilotAutoRefresh(){if(pilotPoller)return;pilotPoller=setInterval(async()=>{if(!document.querySelector('#pilot.panel.active'))return stopPilotAutoRefresh();try{live=await getLiveSessions();renderPilot()}catch(error){console.error(error)}},1500)}
function stopPilotAutoRefresh(){if(!pilotPoller)return;clearInterval(pilotPoller);pilotPoller=null}
function titleFor(quizId){return flat().find(i=>i.quiz?.id===quizId)?.quiz?.title||'Quiz'}
function showTheme(id,b){document.querySelectorAll('.theme-tags .tab').forEach(x=>x.classList.remove('active'));b?.classList.add('active');const theme=catalog.find(t=>t.id===id),box=document.querySelector('#accordions');if(!box||!theme)return;box.innerHTML=`<div class="library-actions"><span class="tag">Thème sélectionné · ${esc(theme.name)}</span><button class="icon-button danger" title="Supprimer ce thème" aria-label="Supprimer le thème" onclick="removeTheme('${theme.id}')">🗑️</button></div>`+(theme.chapters||[]).map(c=>{const qz=Array.isArray(c.quizzes)?c.quizzes[0]:c.quizzes;return `<details class="chapter-accordion"><summary><span class="chapter-icon">📚</span><span><b>${esc(c.title)}</b><small>${qz?.questions?.length||0} question(s)</small></span><button class="icon-button danger" type="button" title="Supprimer ce chapitre" aria-label="Supprimer le chapitre" onclick="event.preventDefault();event.stopPropagation();removeChapter('${c.id}')">🗑️</button><span class="chevron">⌄</span></summary><div class="chapter-content">${(qz?.questions||[]).map((q,n)=>`<article class="question-row"><span class="question-number">${n+1}</span><div style="flex:1"><div class="question-title"><b>${esc(q.body)}</b><span class="question-actions"><button class="icon-button" type="button" title="Modifier la question" aria-label="Modifier la question" onclick="editQuestion('${q.id}')">✏️</button><button class="icon-button archive-button" type="button" title="Archiver la question" aria-label="Archiver la question" onclick="archiveQuestion('${q.id}')">📦</button><button class="icon-button danger" type="button" title="Supprimer la question" aria-label="Supprimer la question" onclick="removeQuestion('${q.id}')">🗑️</button></span></div><div class="answer-preview">${(q.answer_options||[]).map(o=>`<button class="answer-chip" title="Modifier la proposition" onclick="editOption('${o.id}')">${o.label} · ${esc(o.body)} ✏️</button>`).join('')}</div></div></article>`).join('')||'<p class="muted">Aucune question dans ce chapitre.</p>'}</div></details>`}).join('')}
function optionEntry(id){for(const theme of catalog){for(const chapter of theme.chapters||[]){const quiz=Array.isArray(chapter.quizzes)?chapter.quizzes[0]:chapter.quizzes;for(const question of quiz?.questions||[]){const option=(question.answer_options||[]).find(item=>item.id===id);if(option)return{theme,question,option}}}}return null}
async function editOption(id){const entry=optionEntry(id);if(!entry)return alert('Proposition introuvable.');showQuestionForm(entry.question.id)}
function questionEntry(id){for(const theme of catalog){for(const chapter of theme.chapters||[]){const quiz=Array.isArray(chapter.quizzes)?chapter.quizzes[0]:chapter.quizzes;const question=(quiz?.questions||[]).find(item=>item.id===id);if(question)return{theme,chapter,question}}}return null}
async function editQuestion(id){const entry=questionEntry(id);if(!entry)return alert('Question introuvable.');showQuestionForm(id)}
async function removeQuestion(id){const entry=questionEntry(id);if(!entry)return;const label=`Question ${entry.question.position||''} · ${entry.question.body}`.trim();if(!confirm(`Supprimer définitivement « ${label} » ?\n\nSes propositions seront également supprimées. Cette action est irréversible.`))return;try{await deleteQuestionById(id);await refreshQuestions(entry.theme.id)}catch(error){alert(`Suppression impossible : ${error.message}\n\nSi cette question a déjà été utilisée dans une session, elle doit être conservée pour préserver les résultats.`)}}
async function removeTheme(id){const theme=catalog.find(item=>item.id===id);if(!theme)return;const chapters=theme.chapters||[];if(!confirm(`Supprimer définitivement le thème « ${theme.name} » ?\n\nCela supprimera aussi ${chapters.length} chapitre(s), leurs quiz, questions et propositions. Cette action est irréversible.`))return;try{await deleteThemeById(id);await load();render();panel('questions');showTheme(catalog[0]?.id)}catch(e){alert(`Suppression impossible : ${e.message}\n\nSi ce thème a déjà été utilisé dans une session live, terminez ou supprimez d’abord les sessions associées.`)}}
async function removeChapter(id){let entry=null;for(const theme of catalog){const chapter=(theme.chapters||[]).find(item=>item.id===id);if(chapter){entry={theme,chapter};break}}if(!entry)return;const quiz=Array.isArray(entry.chapter.quizzes)?entry.chapter.quizzes[0]:entry.chapter.quizzes;const count=quiz?.questions?.length||0;if(!confirm(`Supprimer définitivement le chapitre « ${entry.chapter.title} » ?\n\nSon quiz, ses ${count} question(s) et leurs propositions seront supprimés. Cette action est irréversible.`))return;try{await deleteChapterById(id);await refreshQuestions(entry.theme.id)}catch(e){alert(`Suppression impossible : ${e.message}\n\nSi ce chapitre a déjà été utilisé dans une session live, terminez ou supprimez d’abord les sessions associées.`)}}
async function refreshQuestions(themeId){await load();render();panel('questions');showTheme(themeId)}
async function createSession(){try{const profile=await getInstructorProfile(),quizId=document.querySelector('#quizSelect').value,title=document.querySelector('#sessionTitle').value.trim()||titleFor(quizId),s=await createLiveSession({code:code(),quiz_id:quizId,instructor_id:profile.id,status:'waiting'});await load();render();document.querySelector('#createdSession').innerHTML=`<div class="card center pop-in"><span class="tag">Session créée</span><h2>${esc(title)}</h2><img class="generated-qr" src="${qr(s.code)}"><div class="code">${s.code}</div><input readonly value="${esc(urlFor(s.code))}"></div>`}catch(e){alert(e.message)}}
function quizForSession(s){return flat().find(i=>i.quiz?.id===s.quiz_id)?.quiz}
function participantName(participant){return `${participant.app_users?.first_name||''} ${participant.app_users?.last_name||''}`.trim()||'Participant'}
function participantInitials(participant){return `${participant.app_users?.first_name?.[0]||''}${participant.app_users?.last_name?.[0]||''}`.toUpperCase()||'?' }
function selectedLabels(session,question,participantId){const labels=new Map((question?.answer_options||[]).map(option=>[option.id,option.label]));return (session.live_answers||[]).filter(answer=>answer.question_id===question?.id&&answer.participant_id===participantId).map(answer=>labels.get(answer.option_id)).filter(Boolean).sort()}
function submissionFor(session,questionId,participantId){return (session.live_answer_submissions||[]).find(item=>item.question_id===questionId&&item.participant_id===participantId)}
function renderArrivalBoard(session,waiting){if(!waiting.length)return '';return `<section class="arrival-board"><div class="row"><div><p class="eyebrow">Tableau des arrivées</p><h3>Participants en attente</h3></div><span class="count-badge">${waiting.length}</span></div><div class="arrival-grid">${waiting.map(participant=>`<button class="arrival-person" type="button" onclick="approve('${participant.id}')" title="Accepter ce participant"><span class="avatar-initials">${esc(participantInitials(participant))}</span><span><b>${esc(participantName(participant))}</b><small>en attente · cliquer pour accepter</small></span></button>`).join('')}</div><button class="button accept-all" type="button" onclick="approveAll('${session.id}')">✓ Accepter tout le monde</button></section>`}
function renderResponseTracking(session,quiz){const question=(quiz?.questions||[]).find(item=>item.id===session.current_question_id);if(!question)return '';const participants=(session.session_participants||[]).filter(item=>item.status==='joined'),options=question.answer_options||[];return `<section class="response-tracking"><div class="row"><div><p class="eyebrow">Suivi détaillé</p><h3>Réponses à la question ${question.position||''}</h3></div><span class="tag">${participants.length} participant(s)</span></div><p class="muted response-question">${esc(question.body)}</p><div class="table-wrap"><table class="response-matrix"><thead><tr><th>Participant</th>${options.map(option=>`<th title="${esc(option.body)}">${option.label}</th>`).join('')}<th>Résultat</th></tr></thead><tbody>${participants.map(participant=>{const labels=new Set(selectedLabels(session,question,participant.id)),submission=submissionFor(session,question.id,participant.id);return `<tr><td><b>${esc(participantName(participant))}</b></td>${options.map(option=>`<td class="matrix-cell ${labels.has(option.label)?'selected':''}">${labels.has(option.label)?'✓':'—'}</td>`).join('')}<td>${submission?`<span class="result-pill ${submission.is_correct?'correct':'incorrect'}">${submission.is_correct?'Correct':'Incorrect'}</span>`:'<span class="result-pill pending">En attente</span>'}</td></tr>`}).join('')||`<tr><td colspan="${options.length+2}">Aucun participant admis.</td></tr>`}</tbody></table></div></section>`}
function renderPilot(){const box=document.querySelector('#pilotRows');if(!box)return;box.innerHTML=live.length?live.map(session=>{const quiz=quizForSession(session),target=(quiz?.questions||[]).find(question=>question.id===session.current_question_id)||quiz?.questions?.[0],waiting=(session.session_participants||[]).filter(participant=>participant.status==='waiting_list'),joined=(session.session_participants||[]).filter(participant=>participant.status==='joined'),hasQuestion=Boolean(session.current_question_id),canReveal=session.status==='polling',answered=new Set((session.live_answer_submissions||[]).filter(item=>item.question_id===session.current_question_id).map(item=>item.participant_id)).size,allAnswered=joined.length>0&&answered>=joined.length;return `<article class="card session-control-card"><div class="row"><h2>${session.code} · ${esc(quiz?.title||'Quiz')}</h2><span class="tag">${session.status}</span></div><div class="actions"><button class="button" onclick="start('${session.id}','${target?.id||''}')">▶ Lancer / reprendre</button><button class="button secondary ${canReveal?'poll-ready':''}" onclick="showAnswers('${session.id}')" ${canReveal?'':'disabled'}>👁 Afficher les réponses</button><button class="button secondary" onclick="next('${session.id}')" ${hasQuestion?'':'disabled'}>Suivant →</button><button class="button danger" onclick="finish('${session.id}')">■ Terminer</button><button class="icon-button archive-button" onclick="archiveActive('session','${session.id}','Session ${esc(session.code)}')" title="Archiver la session" aria-label="Archiver la session">📦</button></div>${hasQuestion?`<p class="response-progress ${allAnswered?'complete':''}">${answered}/${joined.length} participant(s) ont répondu à cette question.</p>`:''}<p class="muted">Le sondage s’affiche automatiquement à la fin du chrono ou dès que tous les participants ont répondu. Utilisez ensuite « Afficher les réponses » pour dévoiler la correction.</p>${renderArrivalBoard(session,waiting)}${renderResponseTracking(session,quiz)}</article>`}).join(''):'<div class="card empty">Créez une session avant de la piloter.</div>';enhancePodiumControls()}
async function start(id,qid){if(!qid)return alert('Aucune question disponible.');const session=live.find(item=>item.id===id),question=(quizForSession(session)?.questions||[]).find(item=>item.id===qid),duration=Math.max(5,Number(question?.duration_seconds)||30);await updateLiveSession(id,{status:'live',podium_visible:false,current_question_id:qid,question_started_at:new Date().toISOString(),question_ends_at:new Date(Date.now()+duration*1000).toISOString()});await refresh()}
async function showAnswers(id){await updateLiveSession(id,{status:'waiting',podium_visible:false});await refresh()}
async function showPodium(id){await updateLiveSession(id,{podium_visible:true});await refresh()}
async function next(id){const s=live.find(x=>x.id===id),q=(quizForSession(s)?.questions||[]),i=q.findIndex(x=>x.id===s.current_question_id),nextQ=q[i+1];if(!nextQ)return finish(id);await updateLiveSession(id,{status:'waiting',podium_visible:false,current_question_id:nextQ.id,question_started_at:null,question_ends_at:null});await refresh()}
async function finish(id){await updateLiveSession(id,{status:'finished',podium_visible:false,ended_at:new Date().toISOString()});await refresh()}
async function approve(id){await rpc('approve_live_participant',{p_participant_id:id});await refresh()}
async function approveAll(sessionId){const session=live.find(item=>item.id===sessionId),waiting=(session?.session_participants||[]).filter(item=>item.status==='waiting_list');try{for(const participant of waiting)await rpc('approve_live_participant',{p_participant_id:participant.id});await refresh()}catch(error){alert(error.message)}}
async function refresh(){await load();render();panel('pilot')}
const archiveTypeLabel={session:'Session live',group:'Groupe de formation',exam:'Examen final',experience:'Expérience pratique',certificate:'Certificat',participant:'Participant',question:'Question'};
function archiveQuestion(id){const entry=questionEntry(id);return archiveActive('question',id,entry?.question?.body||'cette question')}
async function archiveActive(type,id,label){if(!confirm(`Archiver « ${label} » ?\n\nL’élément disparaîtra des listes actives, mais ses données et résultats seront conservés et pourront être restaurés.`))return;try{await archiveItem(type,id);await load();render();const target={question:'questions',session:'pilot',group:'groups',exam:'finalExam',experience:'experiences',certificate:'certificates',participant:'participants'}[type];if(['groups','finalExam','experiences','certificates'].includes(target))openFinalPanel(target);else panel(target)}catch(error){alert(error.message)}}
function renderArchives(){const box=document.querySelector('#archiveRows');if(!box)return;const page=pageItems(archives,'archives');box.innerHTML=`${paginationHtml('archives',archives.length)}<div class="card table-wrap"><table class="archive-table"><thead><tr><th>Type</th><th>Élément</th><th>Détails</th><th>Archivé le</th><th>Actions</th></tr></thead><tbody>${page.items.map(item=>`<tr><td><span class="tag">${esc(archiveTypeLabel[item.type]||item.type)}</span></td><td><b>${esc(item.label)}</b></td><td>${esc(item.details||'—')}</td><td>${participantDate(item.archived_at)}</td><td><div class="archive-actions"><button class="icon-button" type="button" onclick="restoreArchivedItem('${item.type}','${item.id}')" title="Restaurer" aria-label="Restaurer">↩️</button><button class="icon-button danger" type="button" onclick="permanentlyDeleteArchive('${item.type}','${item.id}')" title="Supprimer définitivement" aria-label="Supprimer définitivement">🗑️</button></div></td></tr>`).join('')||'<tr><td colspan="5">Aucune archive.</td></tr>'}</tbody></table></div>${paginationHtml('archives',archives.length)}`}
async function restoreArchivedItem(type,id){if(!confirm('Restaurer cet élément dans les listes actives ?'))return;try{await restoreArchive(type,id);archives=await getArchives();renderArchives();alert('Élément restauré.')}catch(error){alert(error.message)}}
async function permanentlyDeleteArchive(type,id){const item=archives.find(entry=>entry.type===type&&entry.id===id),label=item?.label||'cet élément';if(!confirm(`Supprimer définitivement « ${label} » ?\n\nCette action efface les données concernées et ne peut pas être annulée. Une sauvegarde de la base est recommandée avant de continuer.`))return;try{await deleteArchive(type,id);archives=await getArchives();renderArchives()}catch(error){alert(`Suppression impossible : ${error.message}`)}}
function exportArchives(){const rows=[['Type','Élément','Détails','Date d’archivage'],...archives.map(item=>[archiveTypeLabel[item.type]||item.type,item.label,item.details||'',item.archived_at])],cell=value=>`"${String(value??'').replace(/"/g,'""').replace(/[\r\n]+/g,' ')}"`,csv=`\uFEFF${rows.map(row=>row.map(cell).join(';')).join('\r\n')}\r\n`,url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='archives-quiz.csv';link.click();URL.revokeObjectURL(url)}
const participantDate=value=>value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'—';
function participantFilter(field,value){participantState[field]=value;listPages.participants=0;if(field==='themeId'){participantState.chapterId='';participantState.sessionId=''}if(field==='chapterId')participantState.sessionId='';renderParticipants()}
function participantSearch(value){participantState.search=value;listPages.participants=0;renderParticipants();const input=document.querySelector('#participantSearch');if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length)}}
function participantMatchesFilters(participant){const search=participantState.search.trim().toLocaleLowerCase('fr'),name=`${participant.first_name} ${participant.last_name} ${participant.participant_code||''}`.toLocaleLowerCase('fr');if(search&&!name.includes(search))return false;return(participant.participations||[]).some(item=>(!participantState.themeId||item.theme_id===participantState.themeId)&&(!participantState.chapterId||item.chapter_id===participantState.chapterId)&&(!participantState.sessionId||item.session_id===participantState.sessionId))}
function uniqueParticipantOptions(items,idKey,labelKey){const map=new Map();for(const item of items)if(item[idKey]&&!map.has(item[idKey]))map.set(item[idKey],item[labelKey]);return[...map].sort((a,b)=>String(a[1]).localeCompare(String(b[1]),'fr'))}
function renderParticipants(){const box=document.querySelector('#participantRows');if(!box)return;const allParticipations=participants.flatMap(participant=>participant.participations||[]),themes=uniqueParticipantOptions(allParticipations,'theme_id','theme_name'),chapterSource=allParticipations.filter(item=>!participantState.themeId||item.theme_id===participantState.themeId),chapters=uniqueParticipantOptions(chapterSource,'chapter_id','chapter_title'),sessionSource=chapterSource.filter(item=>!participantState.chapterId||item.chapter_id===participantState.chapterId),sessions=uniqueParticipantOptions(sessionSource,'session_id','session_code'),filtered=participants.filter(participantMatchesFilters),page=pageItems(filtered,'participants');box.innerHTML=`<div class="card participant-filters"><div><label for="participantSearch">Rechercher</label><input id="participantSearch" value="${esc(participantState.search)}" placeholder="Nom, prénom ou code" oninput="participantSearch(this.value)"></div><div><label for="participantTheme">Thème</label><select id="participantTheme" onchange="participantFilter('themeId',this.value)"><option value="">Tous les thèmes</option>${themes.map(([id,label])=>`<option value="${id}" ${id===participantState.themeId?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div><label for="participantChapter">Chapitre</label><select id="participantChapter" onchange="participantFilter('chapterId',this.value)"><option value="">Tous les chapitres</option>${chapters.map(([id,label])=>`<option value="${id}" ${id===participantState.chapterId?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div><label for="participantSession">Session</label><select id="participantSession" onchange="participantFilter('sessionId',this.value)"><option value="">Toutes les sessions</option>${sessions.map(([id,label])=>`<option value="${id}" ${id===participantState.sessionId?'selected':''}>${esc(label)}</option>`).join('')}</select></div></div><div class="card participant-list"><div class="row"><p class="muted">${filtered.length} participant(s) affiché(s)</p><span class="tag">Codes confidentiels</span></div>${paginationHtml('participants',filtered.length)}<div class="table-wrap"><table class="participant-table"><thead><tr><th>Nom</th><th>Prénom</th><th>Code personnel</th><th>Création</th><th>Dernière activité</th><th>Quiz</th><th>Actions</th></tr></thead><tbody>${page.items.map(participant=>{const quizCount=new Set((participant.participations||[]).map(item=>item.quiz_id)).size;return`<tr><td><b>${esc(participant.last_name)}</b></td><td>${esc(participant.first_name)}</td><td><code>${esc(participant.participant_code||'À générer')}</code></td><td>${participantDate(participant.created_at)}</td><td>${participantDate(participant.last_activity)}</td><td>${quizCount}</td><td><div class="row-actions"><button class="icon-button" type="button" onclick="editParticipant('${participant.id}')" title="Modifier le nom" aria-label="Modifier le participant">✏️</button><button class="button secondary" type="button" onclick="regenerateCode('${participant.id}')">Régénérer</button><button class="icon-button archive-button" type="button" onclick="archiveParticipant('${participant.id}')" title="Archiver" aria-label="Archiver le participant">📦</button></div></td></tr>`}).join('')||'<tr><td colspan="7">Aucun participant ne correspond aux filtres.</td></tr>'}</tbody></table></div>${paginationHtml('participants',filtered.length)}</div>`}
async function refreshParticipants(){try{participants=await getParticipants();renderParticipants()}catch(error){const box=document.querySelector('#participantRows');if(box)box.innerHTML=`<div class="notice">${esc(error.message)}</div>`}}
async function regenerateCode(id){const participant=participants.find(item=>item.id===id);if(!participant)return;if(!confirm(`Générer un nouveau code pour ${participant.first_name} ${participant.last_name} ?\n\nL’ancien code ne permettra plus de se reconnecter.`))return;try{const result=await regenerateParticipantCode(id);participant.participant_code=result.participant_code;renderParticipants();alert(`Nouveau code : ${result.participant_code}`)}catch(error){alert(error.message)}}
async function editParticipant(id){const participant=participants.find(item=>item.id===id);if(!participant)return;const firstName=prompt('Prénom de l’apprenant :',participant.first_name);if(firstName===null)return;const lastName=prompt('Nom de l’apprenant :',participant.last_name);if(lastName===null)return;try{await updateParticipant(id,{first_name:firstName.trim(),last_name:lastName.trim()});participants=await getParticipants();renderParticipants()}catch(error){alert(error.message)}}
function archiveParticipant(id){const participant=participants.find(item=>item.id===id);return archiveActive('participant',id,participant?`${participant.first_name} ${participant.last_name}`:'ce participant')}
function quizForChapter(chapter){return Array.isArray(chapter?.quizzes)?chapter.quizzes[0]:chapter?.quizzes}
function selectPerformanceTheme(themeId){const theme=catalog.find(item=>item.id===themeId),chaptersBox=document.querySelector('#performanceChapters'),sessionBox=document.querySelector('#performanceSession'),resultsBox=document.querySelector('#performanceRows');if(!theme||!chaptersBox||!resultsBox)return;performanceState.themeId=themeId;performanceState.chapterId='';performanceState.sessionId='';performanceState.questionPage=0;document.querySelectorAll('#performanceThemes .tab').forEach(button=>button.classList.toggle('active',button.dataset.themeId===themeId));chaptersBox.innerHTML=(theme.chapters||[]).map(chapter=>{const quiz=quizForChapter(chapter);return `<button class="tab" type="button" data-chapter-id="${chapter.id}" onclick="selectPerformanceChapter('${chapter.id}')" ${quiz?'':'disabled'}>📚 ${esc(chapter.title)}</button>`}).join('')||'<span class="muted">Ce thème ne contient aucun chapitre.</span>';if(sessionBox)sessionBox.innerHTML='';resultsBox.innerHTML='Sélectionnez maintenant un chapitre pour afficher les performances.'}
async function selectPerformanceChapter(chapterId){const theme=catalog.find(item=>item.id===performanceState.themeId),chapter=(theme?.chapters||[]).find(item=>item.id===chapterId),quiz=quizForChapter(chapter);if(!theme||!chapter||!quiz)return;performanceState.chapterId=chapterId;performanceState.questionPage=0;document.querySelectorAll('#performanceChapters .tab').forEach(button=>button.classList.toggle('active',button.dataset.chapterId===chapterId));await load();const sessions=live.filter(item=>item.quiz_id===quiz.id);performanceState.sessionId=sessions.some(item=>item.id===performanceState.sessionId)?performanceState.sessionId:(sessions[0]?.id||'');renderPerformanceSessionSelector(sessions);await showPerformance(false)}
function renderPerformanceSessionSelector(sessions){const box=document.querySelector('#performanceSession');if(!box)return;if(!sessions.length){box.innerHTML='<p class="performance-session-note muted">Aucune session n’a encore été créée pour ce chapitre.</p>';return}box.innerHTML=`<div class="performance-session-select"><label for="performanceSelect">Session analysée</label><select id="performanceSelect" onchange="selectPerformanceSession(this.value)">${sessions.map(session=>`<option value="${session.id}" ${session.id===performanceState.sessionId?'selected':''}>${esc(session.code)} · ${esc(session.status)}</option>`).join('')}</select><small>La session la plus récente est affichée automatiquement.</small></div>`}
async function selectPerformanceSession(sessionId){performanceState.sessionId=sessionId;performanceState.questionPage=0;await showPerformance(false)}
async function changePerformanceQuestionPage(direction){performanceState.questionPage+=direction;await showPerformance(false)}
async function showPerformance(refreshData=true){const box=document.querySelector('#performanceRows');if(!box||!performanceState.themeId||!performanceState.chapterId)return;if(refreshData)await load();const theme=catalog.find(item=>item.id===performanceState.themeId),chapter=(theme?.chapters||[]).find(item=>item.id===performanceState.chapterId),quiz=quizForChapter(chapter),sessions=live.filter(item=>item.quiz_id===quiz?.id);if(!quiz){box.innerHTML='Le quiz associé à ce chapitre est introuvable.';return}if(!sessions.length){performanceState.sessionId='';box.innerHTML='<div class="empty">Aucune performance disponible : ce chapitre ne possède encore aucune session.</div>';return}let session=sessions.find(item=>item.id===performanceState.sessionId);if(!session){session=sessions[0];performanceState.sessionId=session.id;renderPerformanceSessionSelector(sessions)}const questions=quiz.questions||[],allParticipants=(session.session_participants||[]).filter(item=>item.status==='joined'),participantPage=pageItems(allParticipants,'performance'),participants=participantPage.items,submissions=session.live_answer_submissions||[],questionCount=questions.length,pageCount=Math.max(1,Math.ceil(questionCount/performancePageSize));performanceState.questionPage=Math.min(Math.max(0,performanceState.questionPage),pageCount-1);const pageStart=performanceState.questionPage*performancePageSize,visibleQuestions=questions.slice(pageStart,pageStart+performancePageSize),pagination=questionCount>performancePageSize?`<div class="performance-pagination"><button class="button secondary" type="button" onclick="changePerformanceQuestionPage(-1)" ${performanceState.questionPage===0?'disabled':''}>← Questions précédentes</button><span>Questions ${pageStart+1} à ${Math.min(pageStart+performancePageSize,questionCount)} sur ${questionCount}</span><button class="button secondary" type="button" onclick="changePerformanceQuestionPage(1)" ${performanceState.questionPage>=pageCount-1?'disabled':''}>Questions suivantes →</button></div>`:'';box.innerHTML=`<div class="performance-heading"><div><p class="eyebrow">${esc(theme.name)} · ${esc(chapter.title)}</p><h2>Session ${esc(session.code)}</h2></div><span class="tag">${allParticipants.length} apprenant(s)</span></div><p class="muted">Chaque colonne indique la ou les propositions choisies par l’apprenant. Survolez une réponse pour voir son libellé.</p>${pagination}${paginationHtml('performance',allParticipants.length)}<div class="table-wrap"><table class="performance-table"><thead><tr><th>Apprenant</th>${visibleQuestions.map(question=>`<th title="${esc(question.body)}">Q${question.position||questions.indexOf(question)+1}</th>`).join('')}<th>Réponses</th><th>Bonnes réponses</th><th>Score</th></tr></thead><tbody>${participants.map(participant=>{const mine=submissions.filter(item=>item.participant_id===participant.id),correct=mine.filter(item=>item.is_correct).length;return `<tr><td><b>${esc(participantName(participant))}</b></td>${visibleQuestions.map(question=>{const labels=selectedLabels(session,question,participant.id),submission=submissionFor(session,question.id,participant.id),detail=(question.answer_options||[]).filter(option=>labels.includes(option.label)).map(option=>`${option.label} · ${option.body}`).join(' | ');return `<td title="${esc(detail||'Aucune réponse')}">${labels.length?`<span class="performance-choice ${submission?.is_correct?'correct':'incorrect'}">${labels.join(', ')} ${submission?.is_correct?'✓':'✕'}</span>`:'—'}</td>`}).join('')}<td>${mine.length}/${questionCount}</td><td>${correct}</td><td><b>${questionCount?Math.round(correct*100/questionCount):0}%</b></td></tr>`}).join('')||`<tr><td colspan="${visibleQuestions.length+4}">Aucun apprenant admis.</td></tr>`}</tbody></table></div>${paginationHtml('performance',allParticipants.length)}${pagination}`}
async function logout(){await signOut();login()}
function chapterOptions(themeId){const theme=catalog.find(t=>t.id===themeId);return (theme?.chapters||[]).map(c=>{const qz=Array.isArray(c.quizzes)?c.quizzes[0]:c.quizzes;return `<option value="${c.id}" data-quiz="${qz?.id||''}" ${qz?'':'disabled'}>${esc(c.title)}${qz?'':' (quiz indisponible)'}</option>`}).join('')}
function showQuestionForm(questionId=''){const box=document.querySelector('#questionForm');if(!box)return;const entry=questionId?questionEntry(questionId):null;if(questionId&&!entry)return alert('Question introuvable.');const editing=Boolean(entry),question=entry?.question,options=['A','B','C','D'].map(label=>(question?.answer_options||[]).find(option=>option.label===label));const themeId=entry?.theme.id||catalog[0]?.id,chapterId=entry?.chapter.id||'';box.innerHTML=`<form class="card question-form" onsubmit="submitQuestion(event,'${question?.id||''}')"><div class="row"><h2>${editing?'Modifier la question':'Ajouter une question'}</h2><button type="button" class="button secondary" onclick="closeQuestionForm()">Fermer</button></div><p class="muted">${editing?'Modifiez l’énoncé, les propositions, les bonnes réponses ou la durée.':'Choisissez une structure existante, ou créez un thème et un chapitre dans la base OVH.'}</p><div class="form-grid"><div><label>Thème</label><select id="questionTheme" onchange="syncQuestionChapters()" ${editing?'disabled':''}>${catalog.map(t=>`<option value="${t.id}" ${t.id===themeId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>${editing?'':`<div><label>Nouveau thème <small>(facultatif)</small></label><input id="newTheme" placeholder="Ex. Sécurité biologique"></div>`}<div><label>Chapitre</label><select id="questionChapter" ${editing?'disabled':''}>${chapterOptions(themeId)}</select></div>${editing?'':`<div><label>Nouveau chapitre <small>(facultatif)</small></label><input id="newChapter" placeholder="Ex. Les équipements de protection"></div>`}<div class="full"><label>Question</label><textarea id="questionBody" required placeholder="Saisissez l’énoncé de la question">${esc(question?.body||'')}</textarea></div>${['A','B','C','D'].map((label,index)=>`<div><label>Proposition ${label}</label><input id="answer${index}" required placeholder="Réponse ${label}" value="${esc(options[index]?.body||'')}"></div>`).join('')}<div class="full"><label>Bonne(s) réponse(s)</label><p class="muted">Cochez toutes les propositions correctes. Une ou plusieurs réponses peuvent être justes.</p><div class="correct-choices">${['A','B','C','D'].map((label,index)=>`<label class="inline-choice"><input class="correctAnswer" type="checkbox" value="${index}" ${(editing?options[index]?.is_correct:index===0)?'checked':''}> Proposition ${label}</label>`).join('')}</div></div><div><label>Durée (secondes)</label><input id="questionSeconds" type="number" min="5" max="3600" value="${Number(question?.duration_seconds)||30}" required></div></div><p id="questionError" class="notice hidden"></p><p><button class="button" type="submit">${editing?'Enregistrer les modifications':'Enregistrer la question'} ✓</button></p></form>`;if(editing){const chapterSelect=document.querySelector('#questionChapter');if(chapterSelect)chapterSelect.value=chapterId}box.scrollIntoView({behavior:'smooth',block:'start'})}
function closeQuestionForm(){const box=document.querySelector('#questionForm');if(box)box.innerHTML=''}
function syncQuestionChapters(){const select=document.querySelector('#questionChapter'),themeId=document.querySelector('#questionTheme')?.value;if(select)select.innerHTML=chapterOptions(themeId)}
async function submitQuestion(event,questionId=''){event.preventDefault();const chapter=document.querySelector('#questionChapter'),error=document.querySelector('#questionError'),newTheme=document.querySelector('#newTheme')?.value.trim()||'',newChapter=document.querySelector('#newChapter')?.value.trim()||'';try{const correct=[...document.querySelectorAll('.correctAnswer:checked')].map(input=>Number(input.value));if(!correct.length)throw new Error('Choisissez au moins une bonne réponse.');const answers=[0,1,2,3].map(i=>document.querySelector(`#answer${i}`).value.trim()),payload={body:document.querySelector('#questionBody').value.trim(),answers,correct,seconds:Number(document.querySelector('#questionSeconds').value),explanation:null};if(questionId){const entry=questionEntry(questionId);if(!entry)throw new Error('Question introuvable.');await updateQuestion(questionId,payload);await load();render();panel('questions');showTheme(entry.theme.id);alert('Question mise à jour sur OVH.');return}let quizId=chapter?.selectedOptions?.[0]?.dataset.quiz;if(newTheme){const theme=await createTheme(newTheme);if(!newChapter)throw new Error('Ajoutez aussi le premier chapitre de ce nouveau thème.');quizId=(await createChapterAndQuiz(theme.id,newChapter)).quiz.id}else if(newChapter){quizId=(await createChapterAndQuiz(document.querySelector('#questionTheme').value,newChapter)).quiz.id}if(!quizId)throw new Error('Ce chapitre n’a pas encore de quiz associé.');await createQuestion(quizId,payload);await load();render();panel('questions');showQuestionForm();alert('Question, thème et chapitre enregistrés sur OVH.')}catch(e){error.textContent=e.message;error.classList.remove('hidden')}}

const statusLabel={planned:'Planifié',active:'En cours',finished:'Terminé'};
const formatDate=value=>value?new Intl.DateTimeFormat('fr-FR').format(new Date(`${String(value).slice(0,10)}T12:00:00Z`)):'—';
function finalPanelButton(id){return document.querySelector(`.nav-button[data-final-panel="${id}"]`)}
function openFinalPanel(id){panel(id,finalPanelButton(id));if(id==='certificates')renderCertificatePanel();if(id==='finalExam')renderFinalExamPanel();if(id==='experiences')renderExperiencePanel()}
function groupFormHtml(){return `<form class="card training-group-form" onsubmit="submitTrainingGroup(event)"><h2>Nouveau groupe de formation</h2><p class="muted">Le thème représente la formation. Les sessions et les quiz seront ensuite rattachés à ce groupe.</p><div class="form-grid"><div><label>Thème</label><select id="groupTheme" required>${catalog.map(theme=>`<option value="${theme.id}">${esc(theme.name)}</option>`).join('')}</select></div><div><label>Nom du groupe</label><input id="groupName" required placeholder="Ex. Promotion septembre 2026"></div><div><label>Entreprise cliente</label><input id="groupClient" placeholder="Ex. Entreprise ABC"></div><div><label>Lieu ou modalité</label><input id="groupLocation" placeholder="Ex. Paris · Présentiel"></div><div><label>Date de début</label><input id="groupStart" type="date" required></div><div><label>Date de fin</label><input id="groupEnd" type="date" required></div><div><label>Seuil de réussite (%)</label><input id="groupThreshold" type="number" min="0" max="100" step="0.1" value="70" required></div></div><p><button class="button" type="submit">Créer le groupe</button></p></form>`}
function renderTrainingGroups(){const box=document.querySelector('#trainingGroupRows');if(!box)return;const page=pageItems(groups,'groups');box.innerHTML=`${paginationHtml('groups',groups.length)}${page.items.map(group=>`<article class="card training-group-card"><div class="row"><div><span class="tag">${esc(statusLabel[group.status]||group.status)}</span><h2>${esc(group.name)}</h2><p class="muted">${esc(group.theme_name)} · ${formatDate(group.start_date)} au ${formatDate(group.end_date)}</p></div><div class="group-card-actions"><div class="group-metrics"><b>${group.participant_count||0}</b><small>participant(s)</small></div><button class="icon-button" type="button" onclick="editTrainingGroup('${group.id}')" title="Modifier le groupe" aria-label="Modifier le groupe">✏️</button><button class="icon-button archive-button" type="button" onclick="archiveTrainingGroup('${group.id}')" title="Archiver le groupe" aria-label="Archiver le groupe">📦</button></div></div><div class="group-details"><span>🏢 ${esc(group.client_name||'Entreprise non renseignée')}</span><span>📍 ${esc(group.location||group.modality||'Lieu non renseigné')}</span><span>🎯 Seuil ${Number(group.passing_score)} %</span><span>📡 ${group.session_count||0} session(s)</span></div><label>État du groupe</label><select onchange="changeTrainingGroupStatus('${group.id}',this.value)">${Object.entries(statusLabel).map(([value,label])=>`<option value="${value}" ${group.status===value?'selected':''}>${label}</option>`).join('')}</select></article>`).join('')||'<div class="card empty">Aucun groupe. Créez d’abord le groupe qui suivra cette formation.</div>'}${paginationHtml('groups',groups.length)}`}
function syncSessionQuizzes(){const groupId=document.querySelector('#sessionGroup')?.value,group=groups.find(item=>item.id===groupId),select=document.querySelector('#quizSelect');if(!select)return;const items=group?flat().filter(item=>item.theme.id===group.theme_id):[];select.innerHTML=items.map(item=>`<option value="${item.quiz?.id}">${esc(item.chapter.title)} · ${esc(item.quiz?.title||'Quiz')}</option>`).join('');select.disabled=!items.length;const button=select.closest('.card')?.querySelector('.button');if(button)button.disabled=!group||!items.length}
function enhanceFinalFeatures(){const sidebar=document.querySelector('.sidebar'),section=document.querySelector('.layout>section');if(!sidebar||!section)return;const participantButton=[...sidebar.querySelectorAll('.nav-button')].find(button=>button.getAttribute('onclick')?.includes("'participants'"));const groupButton=document.createElement('button');groupButton.className='nav-button';groupButton.dataset.finalPanel='groups';groupButton.setAttribute('onclick',"openFinalPanel('groups')");groupButton.textContent='🎓 Groupes de formation';sidebar.insertBefore(groupButton,participantButton||sidebar.lastElementChild);const certificateButton=document.createElement('button');certificateButton.className='nav-button';certificateButton.dataset.finalPanel='certificates';certificateButton.setAttribute('onclick',"openFinalPanel('certificates')");certificateButton.textContent='📜 Certificats';sidebar.insertBefore(certificateButton,participantButton||sidebar.lastElementChild);section.insertAdjacentHTML('beforeend',`<div id="groups" class="panel"><p class="eyebrow">Organisation des formations</p><h1>Groupes de formation</h1>${groupFormHtml()}<div id="trainingGroupRows" class="training-group-list"></div></div><div id="certificates" class="panel"><p class="eyebrow">Validation et délivrance</p><h1>Certificats</h1><div class="card"><label>Groupe de formation</label><select id="certificateGroup" onchange="selectCertificateGroup(this.value)"><option value="">Sélectionnez un groupe</option>${groups.map(group=>`<option value="${group.id}">${esc(group.name)} · ${esc(group.theme_name)}</option>`).join('')}</select></div><div id="certificateRows" class="certificate-results"><div class="card empty">Sélectionnez un groupe pour calculer les scores globaux.</div></div></div>`);const quizSelect=document.querySelector('#quizSelect'),firstLabel=quizSelect?.previousElementSibling;if(quizSelect&&firstLabel){firstLabel.textContent='Quiz du thème sélectionné';firstLabel.insertAdjacentHTML('beforebegin',`<label>Groupe de formation</label><select id="sessionGroup" onchange="syncSessionQuizzes()">${groups.filter(group=>group.status!=='finished').map(group=>`<option value="${group.id}">${esc(group.name)} · ${esc(group.theme_name)}</option>`).join('')||'<option value="">Créez d’abord un groupe</option>'}</select>`);syncSessionQuizzes()}renderTrainingGroups()}
async function submitTrainingGroup(event){event.preventDefault();try{const location=document.querySelector('#groupLocation').value.trim();await createTrainingGroup({theme_id:document.querySelector('#groupTheme').value,name:document.querySelector('#groupName').value.trim(),client_name:document.querySelector('#groupClient').value.trim(),start_date:document.querySelector('#groupStart').value,end_date:document.querySelector('#groupEnd').value,location,modality:location,passing_score:Number(document.querySelector('#groupThreshold').value)});await load();render();openFinalPanel('groups');alert('Groupe de formation créé.')}catch(error){alert(error.message)}}
async function changeTrainingGroupStatus(id,status){try{if(status==='finished'&&!confirm('Terminer ce groupe ? Les certificats éligibles pourront ensuite être délivrés.')){renderTrainingGroups();return}await updateTrainingGroup(id,{status});await load();render();openFinalPanel('groups')}catch(error){alert(error.message);renderTrainingGroups()}}
function archiveTrainingGroup(id){const group=groups.find(item=>item.id===id);return archiveActive('group',id,group?.name||'ce groupe')}
async function editTrainingGroup(id){const group=groups.find(item=>item.id===id);if(!group)return;const name=prompt('Nom du groupe :',group.name);if(name===null)return;const client=prompt('Entreprise cliente :',group.client_name||'');if(client===null)return;const location=prompt('Lieu ou modalité :',group.location||group.modality||'');if(location===null)return;const start=prompt('Date de début (AAAA-MM-JJ) :',String(group.start_date).slice(0,10));if(start===null)return;const end=prompt('Date de fin (AAAA-MM-JJ) :',String(group.end_date).slice(0,10));if(end===null)return;const threshold=prompt('Seuil de réussite (%) :',String(group.passing_score));if(threshold===null)return;try{await updateTrainingGroup(id,{name:name.trim(),client_name:client.trim(),location:location.trim(),modality:location.trim(),start_date:start.trim(),end_date:end.trim(),passing_score:Number(threshold)});await load();render();openFinalPanel('groups')}catch(error){alert(error.message)}}
async function createSessionForGroup(){try{const profile=await getInstructorProfile(),groupId=document.querySelector('#sessionGroup')?.value,quizId=document.querySelector('#quizSelect')?.value;if(!groupId)throw new Error('Créez ou sélectionnez un groupe de formation.');if(!quizId)throw new Error('Ce thème ne contient aucun quiz.');const title=document.querySelector('#sessionTitle').value.trim()||titleFor(quizId),s=await createLiveSession({code:code(),quiz_id:quizId,group_id:groupId,instructor_id:profile.id,show_podium:document.querySelector('#sessionPodium')?.checked===true,status:'waiting'});await load();render();document.querySelector('#createdSession').innerHTML=`<div class="card center pop-in"><span class="tag">Session créée</span><h2>${esc(title)}</h2><img class="generated-qr" src="${qr(s.code)}"><div class="code">${s.code}</div><input readonly value="${esc(urlFor(s.code))}"></div>`}catch(error){alert(error.message)}}
function renderCertificatePanel(){const select=document.querySelector('#certificateGroup');if(select&&select.value)selectCertificateGroup(select.value)}
async function selectCertificateGroup(groupId){const box=document.querySelector('#certificateRows');if(!box)return;if(!groupId){box.innerHTML='<div class="card empty">Sélectionnez un groupe pour calculer les scores globaux.</div>';return}box.innerHTML='<div class="card empty">Calcul des résultats…</div>';try{const result=await getTrainingGroupResults(groupId),group=result.group,quizzes=result.quizzes||[],learners=result.participants||[],issued=learners.filter(item=>item.certificate?.status==='issued').length;box.innerHTML=`<div class="card certificate-summary"><div class="row"><div><span class="tag">${esc(statusLabel[group.status]||group.status)}</span><h2>${esc(group.name)} · ${esc(group.theme_name)}</h2><p class="muted">Moyenne de tous les quiz du thème. Un quiz non réalisé compte pour 0.</p></div><div class="actions"><span class="tag">Seuil ${Number(group.passing_score)} %</span>${issued?`<a class="button secondary" href="${groupCertificatesPdfUrl(group.id)}">Télécharger les ${issued} certificat(s)</a>`:''}</div></div></div><div class="card table-wrap"><table class="certificate-table"><thead><tr><th>Apprenant</th>${quizzes.map(quiz=>`<th>${esc(quiz.chapter_title)}</th>`).join('')}<th>Score global</th><th>Décision</th><th>Certificat</th></tr></thead><tbody>${learners.map(learner=>`<tr><td><b>${esc(learner.first_name)} ${esc(learner.last_name)}</b><small>${esc(learner.participant_code||'')}</small></td>${learner.quiz_scores.map(quiz=>`<td><span class="result-pill ${quiz.taken?'correct':'pending'}">${Number(quiz.score).toFixed(1).replace('.',',')} %${quiz.taken?'':' · absent'}</span></td>`).join('')}<td><b>${Number(learner.global_score).toFixed(1).replace('.',',')} %</b></td><td><span class="result-pill ${learner.eligible?'correct':'incorrect'}">${learner.eligible?'Éligible':'Non éligible'}</span></td><td>${certificateActions(group,learner)}</td></tr>`).join('')||`<tr><td colspan="${quizzes.length+4}">Aucun participant rattaché à ce groupe.</td></tr>`}</tbody></table></div>`}catch(error){box.innerHTML=`<div class="notice">${esc(error.message)}</div>`}}
function certificateActions(group,learner){const certificate=learner.certificate;if(certificate?.status==='issued')return `<div class="certificate-actions"><a class="button secondary" href="${certificatePdfUrl(certificate.id)}">PDF</a><button class="button danger" onclick="revokeLearnerCertificate('${group.id}','${certificate.id}')">Révoquer</button><button class="button secondary" onclick="issueLearnerCertificate('${group.id}','${learner.id}',true)">Régénérer</button><button class="icon-button archive-button" onclick="archiveLearnerCertificate('${certificate.id}')" title="Archiver" aria-label="Archiver le certificat">📦</button></div>`;if(!learner.eligible)return '—';if(group.status!=='finished')return '<small class="muted">Terminez le groupe</small>';return `<button class="button" onclick="issueLearnerCertificate('${group.id}','${learner.id}',${certificate?'true':'false'})">${certificate?'Régénérer':'Valider et délivrer'}</button>`}
function archiveLearnerCertificate(id){return archiveActive('certificate',id,'ce certificat')}
async function issueLearnerCertificate(groupId,userId,regenerate=false){if(regenerate&&!confirm('Régénérer ce certificat ? Son ancien QR code ne sera plus valide.'))return;try{await issueCertificate(groupId,userId);await selectCertificateGroup(groupId)}catch(error){alert(error.message)}}
async function revokeLearnerCertificate(groupId,certificateId){if(!confirm('Révoquer ce certificat ? Sa page publique indiquera qu’il n’est plus valide.'))return;try{await revokeCertificate(certificateId);await selectCertificateGroup(groupId)}catch(error){alert(error.message)}}

let activeFinalExamId='';
let activeExperienceGroupId='';
const percent=value=>`${Number(value||0).toFixed(1).replace('.',',')} %`;
const examStatusLabel={draft:'Préparation',open:'Ouvert',closed:'Clôturé'};

function enhanceEvaluationFeatures(){
  const sidebar=document.querySelector('.sidebar'),section=document.querySelector('.layout>section');
  if(!sidebar||!section)return;
  const certificateButton=finalPanelButton('certificates');
  const examButton=document.createElement('button');
  examButton.className='nav-button';examButton.dataset.finalPanel='finalExam';examButton.setAttribute('onclick',"openFinalPanel('finalExam')");examButton.textContent='📝 Examen final';
  sidebar.insertBefore(examButton,certificateButton||sidebar.lastElementChild);
  const experienceButton=document.createElement('button');
  experienceButton.className='nav-button';experienceButton.dataset.finalPanel='experiences';experienceButton.setAttribute('onclick',"openFinalPanel('experiences')");experienceButton.textContent='🧪 Expériences';
  sidebar.insertBefore(experienceButton,certificateButton||sidebar.lastElementChild);
  section.insertAdjacentHTML('beforeend',`<div id="finalExam" class="panel"><p class="eyebrow">Évaluation individuelle</p><h1>Examen final</h1><p class="muted">Cet examen QCM se déroule sur le téléphone ou l’ordinateur de l’apprenant. Il n’est jamais projeté dans PowerPoint.</p><div id="finalExamRows"></div></div><div id="experiences" class="panel"><p class="eyebrow">Évaluation pratique</p><h1>Expériences en laboratoire</h1><p class="muted">Sélectionnez d’abord un thème, puis un groupe. Les apprenants déjà enregistrés seront proposés automatiquement.</p><div class="card evaluation-filters"><div><label>1. Thème</label><select id="experienceTheme" onchange="selectExperienceTheme(this.value)"><option value="">Sélectionnez un thème</option>${catalog.map(theme=>`<option value="${theme.id}">${esc(theme.name)}</option>`).join('')}</select></div><div><label>2. Groupe</label><select id="experienceGroup" onchange="selectExperienceGroup(this.value)" disabled><option value="">Sélectionnez un groupe</option></select></div></div><div id="experienceRows" class="evaluation-results"><div class="card empty">Sélectionnez un thème, puis un groupe.</div></div></div>`);
  const title=document.querySelector('#sessionTitle');
  if(title)title.insertAdjacentHTML('afterend',`<label class="competition-consent"><input id="sessionPodium" type="checkbox"> <span><b>Afficher un podium dans PowerPoint</b><small>Après la correction, l’instructeur pourra afficher les trois meilleurs pseudonymes. Chaque apprenant reste libre de refuser.</small></span></label>`);
  enhancePodiumControls();
}

function enhancePodiumControls(){
  document.querySelectorAll('.session-control-card').forEach((card,index)=>{
    const session=live[index];
    if(!session?.show_podium||card.querySelector('.podium-button'))return;
    const actions=card.querySelector('.actions');
    if(!actions)return;
    const canShow=Boolean(session.current_question_id&&session.question_started_at)&&session.status==='waiting';
    const button=document.createElement('button');
    button.className=`button podium-button${session.podium_visible?' active':''}`;
    button.disabled=!canShow;
    button.textContent=session.podium_visible?'🏆 Podium affiché':'🏆 Afficher le podium';
    button.onclick=()=>showPodium(session.id);
    actions.appendChild(button);
    card.insertAdjacentHTML('afterbegin','<span class="tag podium-enabled">Podium facultatif activé</span>');
  });
}

async function renderFinalExamPanel(){
  const box=document.querySelector('#finalExamRows');if(!box)return;
  box.innerHTML='<div class="card empty">Chargement des examens…</div>';
  try{
    const exams=await getFinalExams(),page=pageItems(exams,'exams');
    box.innerHTML=`<form class="card exam-builder" onsubmit="submitFinalExam(event)"><h2>Créer l’examen d’un groupe</h2><div class="form-grid"><div><label>Groupe de formation</label><select id="examGroup" required><option value="">Sélectionnez un groupe</option>${groups.map(group=>`<option value="${group.id}" ${exams.some(exam=>exam.group_id===group.id)?'disabled':''}>${esc(group.name)} · ${esc(group.theme_name)}${exams.some(exam=>exam.group_id===group.id)?' · examen déjà créé':''}</option>`).join('')}</select></div><div><label>Durée (minutes)</label><input id="examDuration" type="number" min="5" max="480" value="60" required></div><div class="full"><label>Titre</label><input id="examTitle" required placeholder="Ex. Examen final de la formation"></div><div class="full"><label>Consignes</label><textarea id="examInstructions" placeholder="Consignes visibles avant et pendant l’examen"></textarea></div></div><p><button class="button" type="submit">Créer l’examen</button></p></form>${paginationHtml('exams',exams.length)}<div class="exam-list">${page.items.map(exam=>`<div class="exam-list-row"><button class="card exam-list-item ${activeFinalExamId===exam.id?'selected':''}" type="button" onclick="selectFinalExam('${exam.id}')"><span><span class="tag">${esc(examStatusLabel[exam.status]||exam.status)}</span><b>${esc(exam.title)}</b><small>${esc(exam.group_name)} · ${exam.question_count} question(s) · ${Number(exam.total_points||0)} point(s)</small></span><strong>${exam.submission_count||0} copie(s) →</strong></button><div class="row-actions"><button class="icon-button" type="button" onclick="editFinalExam('${exam.id}')" title="Modifier l’examen" aria-label="Modifier l’examen">✏️</button><button class="icon-button archive-button" type="button" onclick="archiveFinalExam('${exam.id}')" title="Archiver l’examen" aria-label="Archiver l’examen">📦</button></div></div>`).join('')||'<div class="card empty">Aucun examen final créé.</div>'}</div>${paginationHtml('exams',exams.length)}<div id="finalExamDetail"></div>`;
    if(activeFinalExamId&&exams.some(exam=>exam.id===activeFinalExamId))await selectFinalExam(activeFinalExamId,false);
  }catch(error){box.innerHTML=`<div class="notice">${esc(error.message)}</div>`}
}

async function submitFinalExam(event){
  event.preventDefault();
  try{
    const created=await createFinalExam({group_id:document.querySelector('#examGroup').value,title:document.querySelector('#examTitle').value.trim(),instructions:document.querySelector('#examInstructions').value.trim(),duration_minutes:Number(document.querySelector('#examDuration').value)});
    activeFinalExamId=created.id;await renderFinalExamPanel();
  }catch(error){alert(error.message)}
}

async function editFinalExam(id){try{const exam=await getFinalExam(id),title=prompt('Titre de l’examen :',exam.title);if(title===null)return;const instructions=prompt('Consignes :',exam.instructions||'');if(instructions===null)return;const payload={title:title.trim(),instructions:instructions.trim()};if(exam.status==='draft'){const duration=prompt('Durée en minutes :',String(exam.duration_minutes));if(duration===null)return;payload.duration_minutes=Number(duration)}await updateFinalExam(id,payload);await renderFinalExamPanel()}catch(error){alert(error.message)}}
async function archiveFinalExam(id){try{const exam=await getFinalExam(id);await archiveActive('exam',id,exam.title)}catch(error){alert(error.message)}}

async function selectFinalExam(id,scroll=true){
  if(activeFinalExamId!==id)listPages.attempts=0;activeFinalExamId=id;const box=document.querySelector('#finalExamDetail');if(!box)return;
  box.innerHTML='<div class="card empty">Chargement de l’examen…</div>';
  try{
    const exam=await getFinalExam(id),editable=exam.status==='draft',total=(exam.questions||[]).reduce((sum,q)=>sum+Number(q.points||0),0),examUrl=`${location.origin}/exam.html?exam=${encodeURIComponent(exam.code)}`,attempts=exam.attempts||[],attemptsPage=pageItems(attempts,'attempts');
    box.innerHTML=`<article class="card exam-detail"><div class="row"><div><span class="tag">${esc(examStatusLabel[exam.status]||exam.status)}</span><h2>${esc(exam.title)}</h2><p class="muted">${esc(exam.group_name)} · ${exam.duration_minutes} min · ${total} point(s)</p></div><div class="exam-qr"><img src="${finalExamQrUrl(exam.id)}" alt="QR code de l’examen"><code>${esc(exam.code)}</code></div></div><div class="actions exam-state-actions">${exam.status==='draft'?`<button class="button" onclick="changeFinalExamStatus('${exam.id}','open')">Ouvrir l’examen</button>`:''}${exam.status==='open'?`<button class="button danger" onclick="changeFinalExamStatus('${exam.id}','closed')">Clôturer l’examen</button>`:''}${exam.status==='closed'?`<button class="button secondary" onclick="changeFinalExamStatus('${exam.id}','open')">Rouvrir l’examen</button>`:''}<button class="button secondary" onclick="copyText('${esc(examUrl)}')">Copier le lien</button></div>${editable?examQuestionForm(exam):''}<section class="exam-questions"><h3>Questions et barème</h3>${(exam.questions||[]).map(question=>`<article class="exam-question-summary"><div><b>Q${question.position}. ${esc(question.body)}</b><small>${Number(question.points)} point(s)</small></div>${editable?`<button class="icon-button danger" onclick="removeFinalExamQuestion('${exam.id}','${question.id}')" title="Supprimer">🗑️</button>`:''}<div class="exam-option-summary">${question.options.map(option=>`<span class="${option.is_correct?'correct':''}">${esc(option.label)} · ${esc(option.body)}${option.is_correct?' ✓':''}</span>`).join('')}</div></article>`).join('')||'<div class="empty">Ajoutez au moins une question.</div>'}</section><section class="exam-attempts"><h3>Copies des apprenants</h3>${paginationHtml('attempts',attempts.length)}<div class="table-wrap"><table><thead><tr><th>Apprenant</th><th>Code</th><th>État</th><th>Points</th><th>Note</th></tr></thead><tbody>${attemptsPage.items.map(attempt=>`<tr><td><b>${esc(attempt.first_name)} ${esc(attempt.last_name)}</b></td><td><code>${esc(attempt.participant_code)}</code></td><td>${attempt.submitted_at?'Rendue':'En cours'}</td><td>${attempt.submitted_at?Number(attempt.score_points||0):'—'} / ${total}</td><td>${attempt.submitted_at?`<b>${percent(attempt.score_percent)}</b>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5">Aucune copie pour le moment.</td></tr>'}</tbody></table></div>${paginationHtml('attempts',attempts.length)}</section></article>`;
    if(scroll)box.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(error){box.innerHTML=`<div class="notice">${esc(error.message)}</div>`}
}

function examQuestionForm(exam){return `<form class="exam-question-form" onsubmit="submitFinalExamQuestion(event,'${exam.id}')"><h3>Ajouter une question</h3><div class="form-grid"><div class="full"><label>Question</label><textarea id="examQuestionBody" required></textarea></div>${['A','B','C','D'].map((label,index)=>`<div><label>Proposition ${label}</label><input id="examAnswer${index}" required></div>`).join('')}<div class="full"><label>Bonne(s) réponse(s)</label><div class="correct-choices">${['A','B','C','D'].map((label,index)=>`<label class="inline-choice"><input class="examCorrect" type="checkbox" value="${index}" ${index===0?'checked':''}> Proposition ${label}</label>`).join('')}</div></div><div><label>Points attribués</label><input id="examPoints" type="number" min="0.1" max="1000" step="0.1" value="1" required></div></div><p><button class="button" type="submit">Ajouter au questionnaire</button></p></form>`}

async function submitFinalExamQuestion(event,examId){event.preventDefault();try{const correct=[...document.querySelectorAll('.examCorrect:checked')].map(input=>Number(input.value));if(!correct.length)throw new Error('Choisissez au moins une bonne réponse.');await createFinalExamQuestion(examId,{body:document.querySelector('#examQuestionBody').value.trim(),answers:[0,1,2,3].map(index=>document.querySelector(`#examAnswer${index}`).value.trim()),correct,points:Number(document.querySelector('#examPoints').value)});await selectFinalExam(examId,false)}catch(error){alert(error.message)}}
async function removeFinalExamQuestion(examId,questionId){if(!confirm('Supprimer cette question de l’examen ?'))return;try{await deleteFinalExamQuestion(questionId);await selectFinalExam(examId,false)}catch(error){alert(error.message)}}
async function changeFinalExamStatus(examId,status){const message=status==='open'?'Ouvrir maintenant cet examen aux apprenants ?':'Clôturer cet examen ? Les copies en cours seront finalisées.';if(!confirm(message))return;try{await updateFinalExam(examId,{status});await renderFinalExamPanel()}catch(error){alert(error.message)}}
async function copyText(value){try{await navigator.clipboard.writeText(value);alert('Lien copié.')}catch{prompt('Copiez ce lien :',value)}}

function renderExperiencePanel(){const theme=document.querySelector('#experienceTheme');if(theme?.value)selectExperienceTheme(theme.value)}
function selectExperienceTheme(themeId){const select=document.querySelector('#experienceGroup'),matching=groups.filter(group=>group.theme_id===themeId);select.innerHTML=`<option value="">Sélectionnez un groupe</option>${matching.map(group=>`<option value="${group.id}">${esc(group.name)}</option>`).join('')}`;select.disabled=!themeId||!matching.length;activeExperienceGroupId='';document.querySelector('#experienceRows').innerHTML='<div class="card empty">Sélectionnez maintenant un groupe.</div>'}
async function selectExperienceGroup(groupId){activeExperienceGroupId=groupId;const box=document.querySelector('#experienceRows');if(!box||!groupId)return;box.innerHTML='<div class="card empty">Chargement des évaluations…</div>';try{const [result,records]=await Promise.all([getTrainingGroupResults(groupId),getPracticalExperiences(groupId)]),learners=result.participants||[],page=pageItems(records,'experiences');box.innerHTML=`<form class="card experience-form" onsubmit="submitExperience(event,'${groupId}')"><h2>Évaluer un cas pratique</h2><div class="form-grid"><div><label>3. Apprenant</label><select id="experienceLearner" required><option value="">Sélectionnez un apprenant</option>${learners.map(learner=>`<option value="${learner.id}">${esc(learner.first_name)} ${esc(learner.last_name)} · ${esc(learner.participant_code)}</option>`).join('')}</select></div><div><label>Nom de l’expérience</label><input id="experienceName" required placeholder="Ex. Manipulation en laboratoire"></div><div><label>Note obtenue</label><input id="experienceScore" type="number" min="0" step="0.1" required></div><div><label>Barème</label><input id="experienceMax" type="number" min="0.1" step="0.1" value="20" required></div><div class="full"><label>Commentaire de l’évaluateur</label><textarea id="experienceComment" placeholder="Points forts, difficultés et observations"></textarea></div></div><p><button class="button" type="submit">Enregistrer l’évaluation</button></p></form>${paginationHtml('experiences',records.length)}<div class="card table-wrap"><table class="experience-table"><thead><tr><th>Apprenant</th><th>Expérience</th><th>Commentaire</th><th>Note</th><th>Date</th><th>Actions</th></tr></thead><tbody>${page.items.map(record=>`<tr><td><b>${esc(record.first_name)} ${esc(record.last_name)}</b><small>${esc(record.participant_code)}</small></td><td>${esc(record.name)}</td><td>${esc(record.comment||'—')}</td><td><b>${Number(record.score)} / ${Number(record.max_score)}</b></td><td>${new Intl.DateTimeFormat('fr-FR').format(new Date(record.evaluated_at))}</td><td><div class="row-actions"><button class="icon-button" onclick="editExperience('${groupId}','${record.id}')" title="Modifier" aria-label="Modifier l’évaluation">✏️</button><button class="icon-button archive-button" onclick="archiveExperience('${groupId}','${record.id}')" title="Archiver" aria-label="Archiver l’évaluation">📦</button></div></td></tr>`).join('')||'<tr><td colspan="6">Aucune expérience évaluée pour ce groupe.</td></tr>'}</tbody></table></div>${paginationHtml('experiences',records.length)}` }catch(error){box.innerHTML=`<div class="notice">${esc(error.message)}</div>`}}
async function submitExperience(event,groupId){event.preventDefault();try{await createPracticalExperience({group_id:groupId,user_id:document.querySelector('#experienceLearner').value,name:document.querySelector('#experienceName').value.trim(),comment:document.querySelector('#experienceComment').value.trim(),score:Number(document.querySelector('#experienceScore').value),max_score:Number(document.querySelector('#experienceMax').value)});await selectExperienceGroup(groupId)}catch(error){alert(error.message)}}
async function editExperience(groupId,id){try{const records=await getPracticalExperiences(groupId),record=records.find(item=>item.id===id);if(!record)return;const name=prompt('Nom de l’expérience :',record.name);if(name===null)return;const comment=prompt('Commentaire :',record.comment||'');if(comment===null)return;const score=prompt('Note obtenue :',String(record.score));if(score===null)return;const maximum=prompt('Barème :',String(record.max_score));if(maximum===null)return;await updatePracticalExperience(id,{name:name.trim(),comment:comment.trim(),score:Number(score),max_score:Number(maximum)});await selectExperienceGroup(groupId)}catch(error){alert(error.message)}}
async function archiveExperience(groupId,id){try{const records=await getPracticalExperiences(groupId),record=records.find(item=>item.id===id);await archiveActive('experience',id,record?.name||'cette expérience')}catch(error){alert(error.message)}}

async function selectCertificateGroupWeighted(groupId){
  const box=document.querySelector('#certificateRows');if(!box)return;if(!groupId){box.innerHTML='<div class="card empty">Sélectionnez un groupe pour calculer les scores globaux.</div>';return}box.innerHTML='<div class="card empty">Calcul des résultats…</div>';
  try{
    const result=await getTrainingGroupResults(groupId),group=result.group,quizzes=result.quizzes||[],learners=result.participants||[],policy=result.policy||{},issued=learners.filter(item=>item.certificate?.status==='issued').length,page=pageItems(learners,'certificates');
    box.innerHTML=`<form class="card grading-policy" onsubmit="saveGradingPolicy(event,'${group.id}')"><div class="row"><div><p class="eyebrow">Barème du score global</p><h2>Choisir les évaluations et leur poids</h2></div><b class="weight-total">Total : <span id="weightTotal">100</span> %</b></div><p class="muted">Une évaluation incluse mais non réalisée compte pour 0. La somme des poids doit être exactement égale à 100 %.</p><div class="grading-grid">${gradingComponent('Quizz standards','gradingQuizzes','gradingQuizWeight',policy.include_quizzes,policy.quiz_weight)}${gradingComponent('Examen final','gradingExam','gradingExamWeight',policy.include_exam,policy.exam_weight)}${gradingComponent('Expériences pratiques','gradingExperience','gradingExperienceWeight',policy.include_experience,policy.experience_weight)}</div><p><button class="button" type="submit">Enregistrer le barème</button></p></form><div class="card certificate-summary"><div class="row"><div><span class="tag">${esc(statusLabel[group.status]||group.status)}</span><h2>${esc(group.name)} · ${esc(group.theme_name)}</h2><p class="muted">Toutes les colonnes des quiz sont conservées, puis complétées par les trois composantes et le score global pondéré.</p></div><div class="actions"><span class="tag">Seuil ${Number(group.passing_score)} %</span>${issued?`<a class="button secondary" href="${groupCertificatesPdfUrl(group.id)}">Télécharger les ${issued} certificat(s)</a>`:''}</div></div></div>${paginationHtml('certificates',learners.length)}<div class="card table-wrap"><table class="certificate-table weighted-results"><thead><tr><th>Apprenant</th>${quizzes.map(quiz=>`<th>${esc(quiz.chapter_title)}</th>`).join('')}<th>Moyenne quiz</th><th>Examen final</th><th>Expériences</th><th>Score global</th><th>Décision</th><th>Certificat</th></tr></thead><tbody>${page.items.map(learner=>`<tr><td><b>${esc(learner.first_name)} ${esc(learner.last_name)}</b><small>${esc(learner.participant_code||'')}</small></td>${learner.quiz_scores.map(quiz=>`<td><span class="result-pill ${quiz.taken?'correct':'pending'}">${percent(quiz.score)}${quiz.taken?'':' · absent'}</span></td>`).join('')}<td><b>${percent(learner.quiz_score)}</b></td><td><span class="result-pill ${learner.exam_submitted?'correct':'pending'}">${percent(learner.exam_score)}${learner.exam_submitted?'':' · absent'}</span></td><td><span class="result-pill ${learner.experience_count?'correct':'pending'}">${percent(learner.experience_score)} · ${learner.experience_count||0} éval.</span></td><td><b>${percent(learner.global_score)}</b></td><td><span class="result-pill ${learner.eligible?'correct':'incorrect'}">${learner.eligible?'Éligible':'Non éligible'}</span></td><td>${certificateActions(group,learner)}</td></tr>`).join('')||`<tr><td colspan="${quizzes.length+8}">Aucun participant rattaché à ce groupe.</td></tr>`}</tbody></table></div>${paginationHtml('certificates',learners.length)}`;
    updateWeightTotal();
  }catch(error){box.innerHTML=`<div class="notice">${esc(error.message)}</div>`}
}
function gradingComponent(label,checkId,weightId,included,weight){return `<label class="grading-component"><input id="${checkId}" type="checkbox" ${included?'checked':''} onchange="toggleGradingWeight('${checkId}','${weightId}')"><span><b>${label}</b><small>Poids dans la note finale</small></span><input id="${weightId}" type="number" min="0" max="100" step="0.1" value="${Number(weight||0)}" ${included?'':'disabled'} oninput="updateWeightTotal()"><em>%</em></label>`}
function toggleGradingWeight(checkId,weightId){const enabled=document.querySelector(`#${checkId}`).checked,input=document.querySelector(`#${weightId}`);input.disabled=!enabled;if(!enabled)input.value=0;updateWeightTotal()}
function updateWeightTotal(){const total=['gradingQuizWeight','gradingExamWeight','gradingExperienceWeight'].reduce((sum,id)=>sum+Number(document.querySelector(`#${id}`)?.value||0),0),box=document.querySelector('#weightTotal');if(box){box.textContent=String(Math.round(total*10)/10).replace('.',',');box.closest('.weight-total')?.classList.toggle('invalid',Math.abs(total-100)>.001)}}
async function saveGradingPolicy(event,groupId){event.preventDefault();try{await updateTrainingGroupGrading(groupId,{include_quizzes:document.querySelector('#gradingQuizzes').checked,quiz_weight:Number(document.querySelector('#gradingQuizWeight').value||0),include_exam:document.querySelector('#gradingExam').checked,exam_weight:Number(document.querySelector('#gradingExamWeight').value||0),include_experience:document.querySelector('#gradingExperience').checked,experience_weight:Number(document.querySelector('#gradingExperienceWeight').value||0)});await selectCertificateGroupWeighted(groupId);alert('Barème du score global enregistré.')}catch(error){alert(error.message)}}

selectCertificateGroup=selectCertificateGroupWeighted;
const renderBase=render;
render=function(){renderBase();enhanceFinalFeatures();enhanceEvaluationFeatures()};
createSession=createSessionForGroup;
